const $=s=>document.querySelector(s);
const demo={
 enemy:[{name:'Shadow Knight',level:40,atk:180,def:120,sigil:'♜',glow:'#873d59'},{name:'Moon Witch',level:15,atk:90,def:80,sigil:'☽',glow:'#5e548e'},null,null,{name:'Abyss Guard',level:15,atk:70,def:130,sigil:'⬡',glow:'#456b85'},null,null],
 player:[null,{name:'Crimson Mage',level:40,atk:160,def:100,sigil:'✦',glow:'#93455d'},{name:'Forest Warden',level:15,atk:80,def:120,sigil:'♧',glow:'#4b795f'},null,null,null,null],
 hand:[{name:'Storm Caller',type:'CHARACTER',level:15,sigil:'ϟ',glow:'#527ba0',description:'ตัวอย่างการ์ดตัวละครธาตุสายฟ้า'},{name:'Mystic Barrier',type:'SPELL',sigil:'◇',glow:'#6c589d',description:'ตัวอย่างการ์ดเวทมนตร์'},{name:'Blood Oath',type:'TRAP',sigil:'♧',glow:'#963f54',description:'ตัวอย่างการ์ดกับดัก'},{name:'Dawn Paladin',type:'CHARACTER',level:15,sigil:'✧',glow:'#99733f',description:'ตัวอย่างการ์ดตัวละครธาตุแสง'},{name:'Evo Crystal',type:'EVOLUTION',sigil:'❖',glow:'#6c4b92',description:'ตัวอย่างการ์ดวิวัฒนาการ'}]
};
function slot(card,back=false){const el=document.createElement('div');el.className='slot'+(back?' back':'')+(card?' filled':' empty');if(card){const art=document.createElement('div');art.className='card-art';art.style.setProperty('--glow',card.glow||'#795b91');const sig=document.createElement('span');sig.className='sigil';sig.textContent=back?'✥':card.sigil;art.append(sig);el.append(art);if(!back){const cap=document.createElement('div');cap.className='card-caption';cap.innerHTML='<b>'+card.name+'</b><small>Lv.'+card.level+' · ATK '+card.atk+' / DEF '+card.def+'</small>';el.append(cap)}else el.title='การ์ดที่ถูก Set (ข้อมูลตัวอย่าง)'}return el}
function render(){const fill=(id,cards,back=false)=>{const root=$(id);root.innerHTML='';cards.forEach(c=>root.append(slot(c,back)))};fill('#enemyField',demo.enemy);fill('#playerField',demo.player);fill('#enemyBack',[null,{back:true},null,null,null],true);fill('#playerBack',[null,null,{back:true},null,null],true);
const hand=$('#hand');hand.innerHTML='';demo.hand.forEach((c,i)=>{const el=document.createElement('button');el.className='hand-card';el.setAttribute('aria-label','เลือก '+c.name);el.innerHTML='<div class="card-art" style="--glow:'+c.glow+'"><span class="sigil">'+c.sigil+'</span></div><div class="card-caption"><b>'+c.name+'</b><small>'+c.type+'</small></div>';el.addEventListener('click',()=>selectCard(c,el));hand.append(el)})}
let selected=null;function selectCard(c,el){document.querySelectorAll('.hand-card').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');selected=c;$('#detailBtn').textContent='ดู '+c.name;toast('เลือก '+c.name)}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),1900)}
function showDetail(){if(!selected){toast('เลือกการ์ดจากมือก่อน');return}$('#dialogContent').innerHTML='<div class="dialog-card"><div class="dialog-art">'+selected.sigil+'</div><div><small>'+selected.type+'</small><h2>'+selected.name+'</h2><p>'+selected.description+'</p><p>ข้อมูลจำลอง · ยังไม่เชื่อมต่อ Game Engine</p></div></div>';$('#cardDialog').showModal()}
$('#detailBtn').addEventListener('click',showDetail);$('#closeDialog').addEventListener('click',()=>$('#cardDialog').close());
$('#phaseBtn').addEventListener('click',()=>{const battle=$('#phaseText').textContent==='MAIN PHASE';$('#phaseText').textContent=battle?'BATTLE PHASE':'MAIN PHASE';$('#phaseBtn').innerHTML=battle?'จบเทิร์น <span>→</span>':'เข้าสู่ Battle Phase <span>→</span>';toast(battle?'แสดงตัวอย่าง Battle Phase':'กลับสู่ Main Phase');});
$('#logToggle').addEventListener('click',()=>$('#logPanel').classList.toggle('open'));$('#closeLog').addEventListener('click',()=>$('#logPanel').classList.remove('open'));render();